//! AAD public disease-topic indexes and their source-labelled independent publisher links.
use super::{common,Adapter,PlanRow};
use crate::guidelines::doc::{GuidelineDoc,Rights};
use crate::guidelines::fetch::Fetcher;
use crate::guidelines::html::{blocks_from_html,sel,text_of};
use crate::guidelines::registry::SourceEntry;
use anyhow::{bail,Context,Result};
use scraper::{ElementRef,Html};
use serde_json::{json,Value};
use std::collections::HashSet;
use url::Url;
pub struct AadDermatology;
// The source also publishes plain, server-rendered highlights without an accordion.
// Require the observed clinical heading and topic namespace; never fall back to an arbitrary main.
fn plain_highlights(title:String,main:ElementRef<'_>,base:&Url)->Result<(String,String,Vec<crate::guidelines::doc::Block>,Vec<Value>)>{
 if !base.path().starts_with("/member/clinical-quality/guidelines/") || !main.select(&sel("h3")).any(|h|text_of(&h).trim()=="Guideline highlights"){bail!("AAD plain highlights template missing")}
 let source=format!("<div id='aad-topic'>{}</div>",main.html());let hash=crate::common::sha256_hex(source.as_bytes());let(blocks,_)=blocks_from_html(&source,Some(base),Some("#aad-topic"));
 if blocks.is_empty(){bail!("AAD plain highlights body empty")}
 let mut links=vec![];for(i,a)in main.select(&sel("a[href]")).enumerate(){if let Some(url)=common::link(base,a.value().attr("href").unwrap_or_default()){links.push(json!({"url":url,"label":text_of(&a),"role":"source_linked_resource","source_locator":format!("main/link/{i}"),"rights":"unknown; independent resource"}));}}
 Ok((title,hash,blocks,links))
}
fn catalog(html:&str,base:&Url)->Result<Vec<(String,String)>>{
 let d=Html::parse_document(html);let main=d.select(&sel("main.col-lg-9")).next().context("AAD catalog main missing")?;let mut rows=Vec::new();let mut seen=HashSet::new();
 for h in main.select(&sel("h2")){let group=text_of(&h);if group!="Academy guidelines"&&group!="Academy pediatric guidelines"{continue;}let list=h.next_siblings().filter_map(ElementRef::wrap).next().context("AAD group list missing")?;if list.value().name()!="ul"{continue;}
  for a in list.select(&sel("a[href]")){let Some(url)=common::link(base,a.value().attr("href").unwrap_or_default())else{continue};let u=Url::parse(&url)?;if u.origin()!=base.origin()||!u.path().starts_with("/member/clinical-quality/guidelines/"){continue;}let title=text_of(&a);if !title.is_empty()&&seen.insert(url.clone()){rows.push((url,title));}}
 }if rows.is_empty(){anyhow::bail!("AAD guideline groups are empty")}Ok(rows)
}

fn topic(html:&str,base:&Url)->Result<(String,String,Vec<crate::guidelines::doc::Block>,Vec<Value>)>{let d=Html::parse_document(html);let title=d.select(&sel("section.content h1")).next().map(|h|text_of(&h)).filter(|t|!t.is_empty()).context("AAD topic title missing")?;let main=d.select(&sel("main.col-lg-9")).next().context("AAD clinical main missing")?;let accordions=main.select(&sel(".accordion-item")).collect::<Vec<_>>();if accordions.is_empty(){return plain_highlights(title,main,base)}let mut source=String::from("<div id='aad-topic'>");let mut links=vec![];let mut groups=vec![];for(i,item)in accordions.iter().enumerate(){let heading=item.select(&sel("h5")).next().map(|x|text_of(&x)).context("AAD highlight heading missing")?;let body=item.select(&sel(".accordion-item-content")).next().context("AAD highlight body missing")?;source.push_str(&format!("<h2>{}</h2>",heading.replace('&',"&amp;").replace('<',"&lt;")));source.push_str(&body.html());groups.push(crate::guidelines::doc::Block{block_id:format!("aad-group-{i}"),kind:crate::guidelines::doc::BlockKind::Paragraph,text:text_of(&body),heading_path:vec![title.clone(),heading.clone()],page:None});for(j,a)in body.select(&sel("a[href]")).enumerate(){if let Some(url)=common::link(base,a.value().attr("href").unwrap_or_default()){links.push(json!({"url":url,"label":text_of(&a),"role":"source_linked_resource","source_section":heading,"source_locator":format!("accordion/{i}/link/{j}"),"rights":"unknown; independent resource"}));}}}for (i,a) in main.select(&sel("a[href]")).enumerate(){if let Some(url)=common::link(base,a.value().attr("href").unwrap_or_default()){links.push(json!({"url":url,"label":text_of(&a),"role":"source_linked_resource","source_locator":format!("main/link/{i}"),"rights":"unknown; independent resource"}));}}source.push_str("</div>");let hash=crate::common::sha256_hex(source.as_bytes());let(mut blocks,_)=blocks_from_html(&source,Some(base),Some("#aad-topic"));blocks.extend(groups);Ok((title,hash,blocks,links))}
fn unresolved(src:&SourceEntry,url:String,e:String)->PlanRow{PlanRow{source_id:src.id.clone(),doc_key:format!("{}-unresolved",common::short_hash(&url)),url,title:None,rendition:Some("html".into()),version:None,extra:json!({"discovery_error":e})}}
#[async_trait::async_trait]impl Adapter for AadDermatology{
 async fn discover(&self,src:&SourceEntry,f:&Fetcher,limit:Option<usize>)->Result<Vec<PlanRow>>{if limit==Some(0){return Ok(vec![])}let cat=f.get_ok(src.catalog_url.as_deref().context("AAD catalog missing")?).await?;let base=Url::parse(&cat.record.final_url)?;let mut rows=vec![];let mut deferred=vec![];for(url,_)in catalog(&cat.text(),&base)?{let page=match f.get_ok(&url).await{Ok(p)=>p,Err(e)=>{deferred.push(unresolved(src,url,format!("{e:#}")));continue;}};let b=Url::parse(&page.record.final_url)?;if b.origin()!=base.origin(){deferred.push(unresolved(src,url,"topic origin changed".into()));continue;}match topic(&page.text(),&b){Ok((title,hash,_,_))=>{let key=common::short_hash(&url);rows.push(PlanRow{source_id:src.id.clone(),doc_key:format!("{key}-{}",&hash[..12]),url,title:Some(title),rendition:Some("html".into()),version:None,extra:json!({"work_key":key,"topic_sha256":hash,"catalog_fetch":cat.record})});},Err(e)=>deferred.push(unresolved(src,url,format!("{e:#}")))}if limit.is_some_and(|n|rows.len()>=n){return Ok(rows)}}let rem=limit.map(|n|n.saturating_sub(rows.len())).unwrap_or(usize::MAX);rows.extend(deferred.into_iter().take(rem));Ok(rows)}
 async fn extract(&self,src:&SourceEntry,f:&Fetcher,row:&PlanRow)->Result<GuidelineDoc>{if let Some(e)=row.extra["discovery_error"].as_str(){bail!("AAD source unresolved: {e}");}let p=f.get_ok(&row.url).await?;let b=Url::parse(&p.record.final_url)?;if b.origin()!=Url::parse(&row.url)?.origin(){bail!("AAD topic origin changed");}let(title,hash,blocks,attachments)=topic(&p.text(),&b)?;if row.extra["topic_sha256"].as_str().is_some_and(|x|x!=hash){bail!("AAD topic changed since discovery");}let mut fetches=vec![];if let Ok(r)=serde_json::from_value::<crate::guidelines::doc::FetchRecord>(row.extra["catalog_fetch"].clone()){fetches.push(r)}fetches.push(p.record);Ok(GuidelineDoc{source_id:src.id.clone(),doc_key:row.doc_key.clone(),work_key:row.extra["work_key"].as_str().map(String::from),title,url:row.url.clone(),item_type:Some("guideline_highlights".into()),status:"unknown".into(),rights:Rights{status:"unknown".into(),note:Some("Topic index and each publisher resource have separate unverified rights.".into()),..Default::default()},blocks,attachments,fetches,warnings:vec!["Source plain HTML or accordion contains guideline highlights, not complete journal manuscripts; strength labels and nested lists remain in source context, with publisher access and rights independently unresolved.".into()],..Default::default()})}
}

#[cfg(all(test, feature = "guideline-fixtures"))]mod tests{use super::*;#[test]fn genuine_catalog_and_atopic_highlights_remain_scoped(){let cat=[include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/aad_dermatology/catalog-1.html")),include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/aad_dermatology/catalog-2.html"))].concat();let html=[include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/aad_dermatology/atopic-1.html")),include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/aad_dermatology/atopic-2.html"))].concat();let u=Url::parse("https://www.aad.org/member/clinical-quality/guidelines").unwrap();assert!(catalog(&cat,&u).unwrap().iter().any(|(u,_)|u.ends_with("/atopic-dermatitis")));let(_,_,b,_)=topic(&html,&u).unwrap();assert!(b.iter().any(|b|b.text.contains("2025 focused update")));assert!(b.iter().any(|b|b.text.contains("Tapinarof")));assert!(b.iter().any(|b|b.text.contains("Phototherapy and systemic agents")));}}

#[cfg(all(test, feature = "guideline-fixtures"))]mod plain_live_highlights{use super::*;
#[test]fn genuine_plain_topics_keep_highlights_conditions_and_independent_links(){let gold:Value=serde_json::from_str(include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/aad_dermatology/plain-highlights.json"))).unwrap();let cases=gold["cases"].as_array().unwrap();assert_eq!(cases.len(),10);for case in cases{let base=Url::parse(case["source_url"].as_str().unwrap()).unwrap();let raw=case["html"].as_str().unwrap();let(title,_,blocks,links)=topic(raw,&base).unwrap();assert_eq!(title,case["title"].as_str().unwrap());assert!(blocks.iter().any(|b|b.text=="Guideline highlights"));assert!(!links.is_empty());if base.path().ends_with("/acne"){assert!(blocks.iter().any(|b|b.text.contains("pneumatic broadband light")&&b.text.contains("adapalene 0.3% gel")));assert!(blocks.iter().any(|b|b.text.contains("Combining systemic antibiotics with benzoyl peroxide")));assert!(links.iter().any(|a|a["url"]=="https://www.jaad.org/article/S0190-9622(23)03389-3/fulltext"));assert!(links.iter().any(|a|a["url"]=="https://www.jaad.org/article/S0190-9622(15)02614-6/fulltext"));}assert!(topic(&raw.replace("Guideline highlights","Unrecognized clinical heading"),&base).is_err());}}
}
